'use client';
/*
  EffortGlass — a frosted-glass "thinking effort" slider.
  The knob is a brain; a zombie lives in the track. The busier the brain,
  the further the zombie backs off. Pull past Low and it eats the brain;
  reach Big Brain and the zombie runs away screaming. Every level has its
  own look (sound asleep, awake, focused, intense, overclocked, big brain),
  and all of it is interpolated from the knob's live spring position.
  At Low the brain sleeps under a night sky in a nightcap, blowing a snot
  bubble that swells as the zombie creeps closer; the bite pops it first.

  Motion: one requestAnimationFrame loop integrates every spring and writes
  transforms / CSS variables straight to the DOM. React only re-renders when
  the level label, the brainless flag or the eating phase actually change.

  Voice (opt-in, `sound`): the zombie mutters Crazy-Dave-style gibberish,
  one line when the knob settles on a level, a tiny syllable per detent while
  dragging, a scream as it flees Big Brain and "nom nom" on the bite. Voice
  recorded by @nextoneforeal. A speech bubble shows the line even when muted.

  Art: zombie redrawn after "Plants Vs Zombies" by SVG Repo (CC0,
  svgrepo.com/svg/518723); brain line art "Brain Illustration 1" by SVG Repo
  (CC0, svgrepo.com/svg/482775).
*/
import { useCallback, useEffect, useId, useLayoutEffect, useRef, useState } from 'react';

const useIsoLayoutEffect = typeof window !== 'undefined' ? useLayoutEffect : useEffect;

export const DEFAULT_LEVELS = [
  { name: 'Low', hint: 'Quick replies. The brain is barely awake.' },
  { name: 'Medium', hint: 'Awake and balanced for everyday questions.' },
  { name: 'High', hint: 'Focused. Neurons firing, works it through.' },
  { name: 'Extra', hint: 'Intense. Explores alternatives, double-checks.' },
  { name: 'Max', hint: 'Overclocked. Every neuron running hot.' },
  { name: 'Big Brain', hint: 'Big Brain mode. Even zombies run.' },
];
const BRAINLESS = { name: 'Brainless', hint: 'The zombie got it. Slide right to grow it back.' };

/* geometry (px) */
const INSET = 6;
const KNOB = 56;
const PAD = INSET + KNOB / 2; // knob centre at either end
const EAT_AT = 0.36; // over-pull past Low, in level steps, that triggers the bite
const ZW = 74; // zombie art size
/* Low "sound asleep": snot bubble size vs. how close the zombie is */
const BUB_NEAR = 6; // effective gap (px, knob centre → zombie front edge) at which the bubble is biggest
const BUB_FAR = 90; // …and at which it has shrunk to its smallest
const BUB_LEAN = 40; // over-pull lean-in counts as this many px of approach
const NAP_STARTLE = 70; // ms after the pop: the brain startles awake
const NAP_BITE = 220; // ms after the pop: the zombie lunges (startle lasts ~150ms)
const NAP_CRUNCH = 190; // ms after the lunge: the bite lands (brainless)
const MUNCH_CHEW = 520; // ms after the bite lands: the zombie chews (two jaw bobs)…
const MUNCH_BURP = 1180; // …then burps…
const MUNCH_END = 2150; // …then idles

