/* lazy Web Audio player: nothing is created until `unlock()` runs (sound on + a user gesture) */
function makeVoice() {
  let ctx = null, out = null, line = null;
  const bufs = new Map(), loading = new Map();
  const v = {
    vol: 0.8,
    get ready() { return !!ctx; },
    unlock() {
      if (typeof window === 'undefined') return;
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return;
      try {
        if (!ctx) { ctx = new AC(); out = ctx.createGain(); out.gain.value = v.vol; out.connect(ctx.destination); }
        if (ctx.state === 'suspended' && ctx.resume) ctx.resume().catch(() => {});
      } catch (_) { ctx = null; }
    },
    load(url) {
      if (!ctx || !url) return Promise.resolve(null);
      if (bufs.has(url)) return Promise.resolve(bufs.get(url));
      if (!loading.has(url)) {
        loading.set(url, fetch(url).then((r) => (r.ok ? r.arrayBuffer() : Promise.reject(r.status)))
          .then((a) => new Promise((res, rej) => ctx.decodeAudioData(a, res, rej)))
          .then((b) => { bufs.set(url, b); return b; })
          .catch(() => { loading.delete(url); return null; }));
      }
      return loading.get(url);
    },
    dur(url) { const b = bufs.get(url); return b ? b.duration : 0; },
    setVolume(x) { v.vol = x; if (out) out.gain.value = x; },
    stop() {
      if (!line) return;
      const l = line; line = null;
      try {
        const t = ctx.currentTime, gp = l.g.gain;
        gp.cancelScheduledValues(t); gp.setValueAtTime(gp.value, t); gp.linearRampToValueAtTime(0, t + 0.03);
        l.src.stop(t + 0.035);   // a quick, click-free cut: no half syllable trails after leaving a level
      } catch (_) {}
    },
    // a full line (stops the previous one) or a short one-shot (`tick`)
    play(url, { gain = 1, rate = 1, tick = false } = {}) {
      const b = bufs.get(url);
      if (!ctx || !b) return false;
      if (ctx.state === 'suspended' && ctx.resume) ctx.resume().catch(() => {});
      const src = ctx.createBufferSource(), g = ctx.createGain();
      src.buffer = b; src.playbackRate.value = rate;
      // lines fade in over 8 ms so a tightly cut clip never starts with a click
      const t = ctx.currentTime;
      if (tick) g.gain.value = gain;
      else { g.gain.setValueAtTime(0, t); g.gain.linearRampToValueAtTime(gain, t + 0.008); }
      src.connect(g); g.connect(out);
      if (!tick) { v.stop(); line = { src, g }; src.onended = () => { if (line && line.src === src) line = null; }; }
      src.start();
      return true;
    },
    close() { v.stop(); if (ctx && ctx.close) ctx.close().catch(() => {}); ctx = null; bufs.clear(); loading.clear(); },
  };
  return v;
}
// → { tick: url, 0: [{ url, text, syl }], … }. A custom entry may be a url (it keeps the default line's
// words and timing for that slot) or { src, text, syl } with its own.
function voiceUrls(voices, base) {
  const b = base == null ? '' : base;
  // relative files get the voice set's revision so a browser never mixes a cached old take with new code
  const abs = (u) => (/^(https?:|data:|blob:|\/)/.test(u) ? u : b + u + (u.includes('?') ? '' : '?v=' + VOICE_REV));
  const m = {};
  const t = voices && voices.tick !== undefined ? voices.tick : VOICE_TICK;
  const t0 = Array.isArray(t) ? t[0] : t;
  m.tick = t0 ? abs(typeof t0 === 'string' ? t0 : t0.src || '') : '';
  for (const k of Object.keys(VOICE_LINES)) {
    const def = VOICE_LINES[k];
    const o = voices && voices[k] !== undefined ? voices[k] : def;
    m[k] = (Array.isArray(o) ? o : o ? [o] : []).map((e, i) => {
      const d = def[i % def.length];
      if (typeof e === 'string') return { url: abs(e), text: d.text, syl: d.syl };
      const text = e.text != null ? e.text : d.text;
      return { url: e.src ? abs(e.src) : '', text, syl: e.syl || (e.text != null ? [{ t: 0, s: text }] : d.syl) };
    });
  }
  return m;
}

/* ---------- math ---------- */
const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
const lerp = (a, b, t) => a + (b - a) * t;
const smooth = (e0, e1, x) => {
  const t = clamp((x - e0) / (e1 - e0), 0, 1);
  return t * t * (3 - 2 * t);
};
const rubber = (d, dim) => (1 - 1 / ((d * 0.55) / dim + 1)) * dim;

/* monotone cubic (Fritsch–Carlson) through the zombie's stand-off curve */
const Z_KNOTS = [0.18, 0.5, 0.715, 0.805, 0.845, 1.32]; // zombie left edge, as a fraction of track width, per level
const Z_TAN = (() => {
  const n = Z_KNOTS.length, d = [], m = [];
  for (let i = 0; i < n - 1; i++) d.push(Z_KNOTS[i + 1] - Z_KNOTS[i]);
  m[0] = d[0]; m[n - 1] = d[n - 2];
  for (let i = 1; i < n - 1; i++) m[i] = d[i - 1] * d[i] <= 0 ? 0 : (d[i - 1] + d[i]) / 2;
  for (let i = 0; i < n - 1; i++) {
    if (d[i] === 0) { m[i] = m[i + 1] = 0; continue; }
    const a = m[i] / d[i], b = m[i + 1] / d[i], h = a * a + b * b;
    if (h > 9) { const t = 3 / Math.sqrt(h); m[i] = t * a * d[i]; m[i + 1] = t * b * d[i]; }
  }
  return m;
})();
function zCurve(s, levels) {
  // s in [0, levels-1] mapped onto the 6 design knots
  const u = clamp((s / Math.max(1, levels - 1)) * (Z_KNOTS.length - 1), 0, Z_KNOTS.length - 1);
  const i = Math.min(Math.floor(u), Z_KNOTS.length - 2), t = u - i;
  const t2 = t * t, t3 = t2 * t;
  return (2 * t3 - 3 * t2 + 1) * Z_KNOTS[i] + (t3 - 2 * t2 + t) * Z_TAN[i] +
    (-2 * t3 + 3 * t2) * Z_KNOTS[i + 1] + (t3 - t2) * Z_TAN[i + 1];
}

/* damped spring, response (s) + damping ratio, integrated in small steps */
function spring(p, target, response, ratio, dt) {
  const k = (2 * Math.PI / response) ** 2, c = (4 * Math.PI * ratio) / response;
  let x = p.x, v = p.v;
  const steps = Math.max(1, Math.ceil(dt / (1 / 240)));
  const h = dt / steps;
  for (let i = 0; i < steps; i++) { v += (-k * (x - target) - c * v) * h; x += v * h; }
  p.x = x; p.v = v;
}

